import { WILDCARD_GROUP, checkNavAccess, decoratedNavChildren, decoratedNavDivisions, generatePathToBreadcrumbsMapForDocsConfig, generatePathToHiddenFromSearchDict, generatePathToLanguageDict, generatePathToVersionDict, isPage, MINT_EXPORT_SEARCH_INDEX_PATH, optionallyRemoveLeadingSlash, } from '@mintlify/common';
import fse from 'fs-extra';
import { fromHtml } from 'hast-util-from-html';
import { toText } from 'hast-util-to-text';
import path from 'path';
const MAX_CONTENT_LENGTH = 2000;
const SKIPPED_TAGS = new Set(['script', 'style', 'svg', 'button', 'noscript', 'template']);
const SECTION_HEADINGS = new Set(['h2', 'h3']);
const isElement = (node) => node.type === 'element';
const getProperty = (element, name) => {
    const value = element.properties[name];
    return typeof value === 'string' ? value : undefined;
};
const isHidden = (element) => SKIPPED_TAGS.has(element.tagName) || element.properties.ariaHidden === 'true';
const REACT_GENERATED_ID = /^(_R_|«|:)/;
const normalizeWhitespace = (text) => text
    .replace(/[\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
function splitContent(text) {
    const chunks = [];
    let current = '';
    for (const word of text.split(' ')) {
        if (current && current.length + word.length + 1 > MAX_CONTENT_LENGTH) {
            chunks.push(current);
            current = `${current.slice(current.lastIndexOf(' ') + 1)} ${word}`;
        }
        else {
            current = current ? `${current} ${word}` : word;
        }
    }
    return [...chunks, current];
}
function findElement(node, predicate) {
    for (const child of node.children) {
        if (!isElement(child))
            continue;
        if (predicate(child))
            return child;
        const found = findElement(child, predicate);
        if (found)
            return found;
    }
    return undefined;
}
function collectSections(content, pageTitle) {
    const sections = [{ header: pageTitle, text: [] }];
    const visit = (node) => {
        if (node.type === 'text') {
            sections[sections.length - 1]?.text.push(node.value);
            return;
        }
        if (!isElement(node) || isHidden(node))
            return;
        const hash = getProperty(node, 'id');
        if (SECTION_HEADINGS.has(node.tagName) && hash && !REACT_GENERATED_ID.test(hash)) {
            sections.push({ header: normalizeWhitespace(toText(node)), hash, text: [] });
            return;
        }
        const isBlock = /^(p|div|li|tr|td|th|pre|h[1-6]|blockquote|section|table|ul|ol)$/.test(node.tagName);
        if (isBlock)
            sections[sections.length - 1]?.text.push(' ');
        node.children.forEach(visit);
        if (isBlock)
            sections[sections.length - 1]?.text.push(' ');
    };
    content.children.forEach(visit);
    return sections;
}
const findById = (tree, id) => findElement(tree, (element) => getProperty(element, 'id') === id);
function getPageTitle(tree, content, page) {
    const frontmatterTitle = getProperty(content, 'dataPageTitle');
    if (frontmatterTitle)
        return frontmatterTitle;
    const heading = findById(tree, 'page-title');
    return heading ? normalizeWhitespace(toText(heading)) : page;
}
function getPageDescription(tree) {
    const meta = findElement(tree, (element) => element.tagName === 'meta' && getProperty(element, 'name') === 'description');
    return meta && getProperty(meta, 'content');
}
export function extractSearchDocuments(html, page, { breadcrumbs, locale, version } = {}) {
    const tree = fromHtml(html);
    const content = findById(tree, 'content') ?? findById(tree, 'content-area');
    if (!content)
        return [];
    const title = getPageTitle(tree, content, page);
    const description = getPageDescription(tree);
    return collectSections(content, title).flatMap((section, index) => {
        const text = section.text.join('');
        const searchableText = index === 0 && description ? `${description} ${text}` : text;
        return splitContent(normalizeWhitespace(searchableText)).map((chunk, part) => ({
            id: `${page}#${index}.${part}`,
            page,
            title,
            header: section.header,
            ...(section.hash && { hash: section.hash }),
            content: chunk,
            ...(breadcrumbs?.length && { breadcrumbs }),
            ...(locale && { locale }),
            ...(version && { version }),
        }));
    });
}
function collectNavPages(node, pages = []) {
    if (isPage(node))
        pages.push(node);
    for (const child of [...decoratedNavChildren(node), ...decoratedNavDivisions(node)]) {
        collectNavPages(child, pages);
    }
    return pages;
}
export function getSearchablePages(generatedNav, docsConfig, groups) {
    const hiddenFromSearch = docsConfig?.seo?.indexing === 'all'
        ? new Map()
        : generatePathToHiddenFromSearchDict(generatedNav);
    const breadcrumbs = docsConfig?.navigation
        ? generatePathToBreadcrumbsMapForDocsConfig(docsConfig.navigation)
        : new Map();
    const languages = generatePathToLanguageDict(generatedNav);
    const versions = generatePathToVersionDict(generatedNav);
    const userGroups = new Set([...(groups ?? []), WILDCARD_GROUP]);
    const pages = new Map();
    for (const navPage of collectNavPages(generatedNav)) {
        const slug = optionallyRemoveLeadingSlash(navPage.href);
        if (pages.has(navPage.href) ||
            hiddenFromSearch.get(slug) ||
            navPage.noindex ||
            navPage.searchable === false ||
            !checkNavAccess(navPage, userGroups, false, false)) {
            continue;
        }
        const locale = languages.get(slug);
        const version = versions.get(slug);
        pages.set(navPage.href, {
            breadcrumbs: breadcrumbs.get(slug),
            ...(locale && { locale }),
            ...(version && { version }),
        });
    }
    return pages;
}
const toPagePath = (route) => route.replace(/\/index$/, '') || '/';
export async function writeSearchIndex(exportDir, { generatedNav, docsConfig, groups, }) {
    const searchablePages = generatedNav
        ? getSearchablePages(generatedNav, docsConfig, groups)
        : new Map();
    const indexedPages = new Set();
    const documents = [];
    for (const [route, info] of searchablePages) {
        const page = toPagePath(route);
        const htmlPath = path.join(exportDir, route, 'index.html');
        if (indexedPages.has(page) || !(await fse.pathExists(htmlPath)))
            continue;
        indexedPages.add(page);
        documents.push(...extractSearchDocuments(await fse.readFile(htmlPath, 'utf8'), page, info));
    }
    await fse.outputJson(path.join(exportDir, MINT_EXPORT_SEARCH_INDEX_PATH), documents);
    return documents.length;
}
